Object.assign(window.IND_FEED_BODY, {"vs-kural-1":{"route":"#/verses/kural","source":"Thirukkural 1 — Book I (Aram), chapter 1, “In praise of God”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-1:text_original","title":"Thirukkural","text":"அகர முதல எழுத்தெல்லாம் ஆதி\nபகவன் முதற்றே உலகு","lang":"ta","roman":"agara mudhala ezhuththellām ādhi\nbagavan mudhatrē ulagu"},"vm-kural-1":{"route":"#/verses/kural","source":"Thirukkural 1 — Book I (Aram), chapter 1, “In praise of God”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-1:meaning_kid","title":"What it means · Thirukkural","body":"A is the first letter — everything written starts there. The poet says the world starts with God in exactly the same way."},"vy-kural-1":{"route":"#/verses/kural","source":"Thirukkural 1 — Book I (Aram), chapter 1, “In praise of God”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-1:why","title":"Why carry it","body":"It is the opening line of a book with 1,330 lines in it, and it begins with the alphabet. The same alphabet somebody is teaching you right now."},"vs-kural-34":{"route":"#/verses/kural","source":"Thirukkural 34 — Book I (Aram), chapter 4, “The strength of virtue”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-34:text_original","title":"Thirukkural","text":"மனத்துக்கண் மாசிலன் ஆதல் அனைத்தறன்\nஆகுல நீர பிற","lang":"ta","roman":"manaththukkaṇ māsilan ādhal anaiththaran\nāgula nīra pira"},"vm-kural-34":{"route":"#/verses/kural","source":"Thirukkural 34 — Book I (Aram), chapter 4, “The strength of virtue”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-34:meaning_kid","title":"What it means · Thirukkural","body":"Being clean inside your own head is the whole of doing right. Everything else people call good is just noise on top."},"vy-kural-34":{"route":"#/verses/kural","source":"Thirukkural 34 — Book I (Aram), chapter 4, “The strength of virtue”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-34:why","title":"Why carry it","body":"You can look completely fine to everybody in the room and still know exactly what you did. This couplet is about the part only you can see."},"vs-kural-80":{"route":"#/verses/kural","source":"Thirukkural 80 — Book I (Aram), chapter 8, “Having love”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-80:text_original","title":"Thirukkural","text":"அன்பின் வழியது உயிர்நிலை அஃதிலார்க்கு\nஎன்புதோல் போர்த்த உடம்பு","lang":"ta","roman":"anbin vazhiyadhu uyirnilai aqdhilārkku\nenbudhōl pōrththa udambu"},"vm-kural-80":{"route":"#/verses/kural","source":"Thirukkural 80 — Book I (Aram), chapter 8, “Having love”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-80:meaning_kid","title":"What it means · Thirukkural","body":"A life with love in it is what being alive actually means. Without it, says the poet, a body is just bones with some skin thrown over them."},"vy-kural-80":{"route":"#/verses/kural","source":"Thirukkural 80 — Book I (Aram), chapter 8, “Having love”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-80:why","title":"Why carry it","body":"It is a shocking thing to say and it is meant to be. Love is not decoration on top of a life. It is the thing that makes it one."},"vs-kural-100":{"route":"#/verses/kural","source":"Thirukkural 100 — Book I (Aram), chapter 10, “Speaking sweetly”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-100:text_original","title":"Thirukkural","text":"இனிய உளவாக இன்னாத கூறல்\nகனிஇருப்பக் காய்கவர்ந் தற்று","lang":"ta","roman":"iniya uḷavāga innādha kūral\nkani-iruppak kāykavarn dhatru"},"vm-kural-100":{"route":"#/verses/kural","source":"Thirukkural 100 — Book I (Aram), chapter 10, “Speaking sweetly”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-100:meaning_kid","title":"What it means · Thirukkural","body":"Saying the mean thing when a kind one was right there is like grabbing the hard sour fruit while the ripe sweet one sat next to it."},"vy-kural-100":{"route":"#/verses/kural","source":"Thirukkural 100 — Book I (Aram), chapter 10, “Speaking sweetly”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-100:why","title":"Why carry it","body":"There were two things you could have said to your friend, and you picked the one that stung. This couplet is about that exact half-second."},"vs-kural-104":{"route":"#/verses/kural","source":"Thirukkural 104 — Book I (Aram), chapter 11, “Knowing what has been done for you”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-104:text_original","title":"Thirukkural","text":"தினைத்துணை நன்றி செயினும் பனைத்துணையாக்\nகொள்வர் பயன்தெரி வார்","lang":"ta","roman":"thinaiththuṇai nandri seyinum panaiththuṇaiyāk\nkoḷvar payandheri vār"},"vm-kural-104":{"route":"#/verses/kural","source":"Thirukkural 104 — Book I (Aram), chapter 11, “Knowing what has been done for you”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-104:meaning_kid","title":"What it means · Thirukkural","body":"Somebody helps you by an amount the size of a millet seed — the tiniest grain there is. A person who understands counts it as big as a palm tree."},"vy-kural-104":{"route":"#/verses/kural","source":"Thirukkural 104 — Book I (Aram), chapter 11, “Knowing what has been done for you”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-104:why","title":"Why carry it","body":"Someone gave you half their snack once when you had none. Small for them. Huge for you. That is the whole couplet, and it is why you still remember it."},"vs-kural-291":{"route":"#/verses/kural","source":"Thirukkural 291 — Book I (Aram), chapter 30, “Truthfulness”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-291:text_original","title":"Thirukkural","text":"வாய்மை எனப்படுவது யாதெனின் யாதொன்றும்\nதீமை இலாத சொலல்","lang":"ta","roman":"vāymai enappaduvadhu yādhenin yādhondrum\nthīmai ilādha solal"},"vm-kural-291":{"route":"#/verses/kural","source":"Thirukkural 291 — Book I (Aram), chapter 30, “Truthfulness”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-291:meaning_kid","title":"What it means · Thirukkural","body":"Somebody asks the poet: what is truth? He answers: words with no harm in them at all, to anybody."},"vy-kural-291":{"route":"#/verses/kural","source":"Thirukkural 291 — Book I (Aram), chapter 30, “Truthfulness”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-291:why","title":"Why carry it","body":"This is a much bigger idea than “do not lie”. You can say something perfectly true and use it to hurt someone. The Kural says that is not truth either."},"vs-kural-314":{"route":"#/verses/kural","source":"Thirukkural 314 — Book I (Aram), chapter 32, “Not causing harm”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-314:text_original","title":"Thirukkural","text":"இன்னா செய்தாரை ஒறுத்தல் அவர்நாண\nநன்னயம் செய்து விடல்","lang":"ta","roman":"innā seydhārai oruththal avarnāṇa\nnannayam seydhu vidal"},"vm-kural-314":{"route":"#/verses/kural","source":"Thirukkural 314 — Book I (Aram), chapter 32, “Not causing harm”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-314:meaning_kid","title":"What it means · Thirukkural","body":"Someone was horrible to you. The way to pay them back, says the poet, is to be so good to them that they end up ashamed of themselves."},"vy-kural-314":{"route":"#/verses/kural","source":"Thirukkural 314 — Book I (Aram), chapter 32, “Not causing harm”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-314:why","title":"Why carry it","body":"Hard. Genuinely hard. But it is the only kind of getting-even that leaves you feeling better afterwards instead of worse."},"vs-kural-391":{"route":"#/verses/kural","source":"Thirukkural 391 — Book I (Aram), chapter 40, “Learning”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-391:text_original","title":"Thirukkural","text":"கற்க கசடறக் கற்பவை கற்றபின்\nநிற்க அதற்குத் தக","lang":"ta","roman":"karka kasadarak karpavai katrapin\nnirka adharkuth thaga"},"vm-kural-391":{"route":"#/verses/kural","source":"Thirukkural 391 — Book I (Aram), chapter 40, “Learning”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-391:meaning_kid","title":"What it means · Thirukkural","body":"Learn the things worth learning, and learn them properly, with no mistakes left in. Then live the way what you learned says to live."},"vy-kural-391":{"route":"#/verses/kural","source":"Thirukkural 391 — Book I (Aram), chapter 40, “Learning”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-391:why","title":"Why carry it","body":"The second line is the hard half. Knowing the right thing and doing the right thing are two completely different jobs, and only one of them is a test."},"vs-kural-396":{"route":"#/verses/kural","source":"Thirukkural 396 — Book I (Aram), chapter 40, “Learning”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-396:text_original","title":"Thirukkural","text":"தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக்\nகற்றனைத் தூறும் அறிவு","lang":"ta","roman":"thottanaith thūrum maṇarkēṇi māndharkkuk\nkatranaith thūrum arivu"},"vm-kural-396":{"route":"#/verses/kural","source":"Thirukkural 396 — Book I (Aram), chapter 40, “Learning”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-396:meaning_kid","title":"What it means · Thirukkural","body":"Dig a hole in wet sand and water comes up. Dig deeper and more comes. Learning works exactly like that inside a person."},"vy-kural-396":{"route":"#/verses/kural","source":"Thirukkural 396 — Book I (Aram), chapter 40, “Learning”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-396:why","title":"Why carry it","body":"You have done this on a beach. Now you know it is also a two-thousand-year-old argument for reading one more chapter."},"vs-kural-423":{"route":"#/verses/kural","source":"Thirukkural 423 — Book I (Aram), chapter 43, “Having wisdom”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-423:text_original","title":"Thirukkural","text":"எப்பொருள் யார்யார்வாய்க் கேட்பினும் அப்பொருள்\nமெய்ப்பொருள் காண்ப தறிவு","lang":"ta","roman":"epporuḷ yāryārvāyk kētpinum apporuḷ\nmeypporuḷ kāṇba dharivu"},"vm-kural-423":{"route":"#/verses/kural","source":"Thirukkural 423 — Book I (Aram), chapter 43, “Having wisdom”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-423:meaning_kid","title":"What it means · Thirukkural","body":"Whoever tells you something, and whatever they tell you, being clever means working out what is actually true in it."},"vy-kural-423":{"route":"#/verses/kural","source":"Thirukkural 423 — Book I (Aram), chapter 43, “Having wisdom”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-423:why","title":"Why carry it","body":"Somebody on a screen said something with total confidence and no proof. This couplet is two thousand years old and it is about that."},"vs-kural-616":{"route":"#/verses/kural","source":"Thirukkural 616 — Book II (Porul), chapter 62, “Unfailing effort”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-616:text_original","title":"Thirukkural","text":"முயற்சி திருவினை ஆக்கும் முயற்றின்மை\nஇன்மை புகுத்தி விடும்","lang":"ta","roman":"muyarchi thiruvinai ākkum muyatrinmai\ninmai puguththi vidum"},"vm-kural-616":{"route":"#/verses/kural","source":"Thirukkural 616 — Book II (Porul), chapter 62, “Unfailing effort”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-616:meaning_kid","title":"What it means · Thirukkural","body":"Trying hard makes good things happen. Not trying brings the exact opposite, and brings it just as reliably."},"vy-kural-616":{"route":"#/verses/kural","source":"Thirukkural 616 — Book II (Porul), chapter 62, “Unfailing effort”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-616:why","title":"Why carry it","body":"It is painted on the wall of a lot of Tamil classrooms, and it is short enough to say to yourself in the ten seconds before a test starts."},"vs-kural-788":{"route":"#/verses/kural","source":"Thirukkural 788 — Book II (Porul), chapter 79, “Friendship”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-788:text_original","title":"Thirukkural","text":"உடுக்கை இழந்தவன் கைபோல ஆங்கே\nஇடுக்கண் களைவதாம் நட்பு","lang":"ta","roman":"udukkai izhandhavan kaipōla āngē\nidukkaṇ kaḷaivadhām naṭpu"},"vm-kural-788":{"route":"#/verses/kural","source":"Thirukkural 788 — Book II (Porul), chapter 79, “Friendship”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-788:meaning_kid","title":"What it means · Thirukkural","body":"When your clothes start to slip, your hand grabs them before you have even thought about it. A friend is the hand. That is the whole couplet."},"vy-kural-788":{"route":"#/verses/kural","source":"Thirukkural 788 — Book II (Porul), chapter 79, “Friendship”","art":null,"cta":"More verses","why":"A verse from Thirukkural","src":"verse:kural-788:why","title":"Why carry it","body":"You do not decide to help a real friend. You notice afterwards that you already did. And you can tell who your friends are by who moves first."},"vs-dhp-1":{"route":"#/verses/dhammapada","source":"Dhammapada 1 — chapter 1, Yamakavagga (“the twin verses”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-1:text_original","title":"Dhammapada","text":"Manopubbaṅgamā dhammā, manoseṭṭhā manomayā;\nmanasā ce paduṭṭhena, bhāsati vā karoti vā;\ntato naṃ dukkham anveti, cakkaṃ va vahato padaṃ.","lang":"pi","roman":"mano-pubbangamā dhammā, mano-seṭṭhā mano-mayā;\nmanasā che paduṭṭhena, bhāsati vā karoti vā;\ntato naṃ dukkham anveti, chakkaṃ va vahato padaṃ."},"vm-dhp-1":{"route":"#/verses/dhammapada","source":"Dhammapada 1 — chapter 1, Yamakavagga (“the twin verses”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-1:meaning_kid","title":"What it means · Dhammapada","body":"Everything you do is a thought first. Speak or act with a spoiled thought behind it and the trouble follows you — like the cart wheel following the ox that is pulling it."},"vy-dhp-1":{"route":"#/verses/dhammapada","source":"Dhammapada 1 — chapter 1, Yamakavagga (“the twin verses”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-1:why","title":"Why carry it","body":"You can feel this one working. The mood you get out of bed in decides an awful lot of what the rest of the day turns out to be."},"vs-dhp-2":{"route":"#/verses/dhammapada","source":"Dhammapada 2 — chapter 1, Yamakavagga (“the twin verses”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-2:text_original","title":"Dhammapada","text":"Manopubbaṅgamā dhammā, manoseṭṭhā manomayā;\nmanasā ce pasannena, bhāsati vā karoti vā;\ntato naṃ sukham anveti, chāyā va anapāyinī.","lang":"pi","roman":"mano-pubbangamā dhammā, mano-seṭṭhā mano-mayā;\nmanasā che pasannena, bhāsati vā karoti vā;\ntato naṃ sukham anveti, chāyā va anapāyinī."},"vm-dhp-2":{"route":"#/verses/dhammapada","source":"Dhammapada 2 — chapter 1, Yamakavagga (“the twin verses”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-2:meaning_kid","title":"What it means · Dhammapada","body":"Same beginning, opposite ending. Speak or act with a clear, settled thought behind it and the happiness follows you like your own shadow, which never once leaves."},"vy-dhp-2":{"route":"#/verses/dhammapada","source":"Dhammapada 2 — chapter 1, Yamakavagga (“the twin verses”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-2:why","title":"Why carry it","body":"Verses 1 and 2 are twins — that is what the chapter is called. Learn them together and you have the shape of the whole book."},"vs-dhp-5":{"route":"#/verses/dhammapada","source":"Dhammapada 5 — chapter 1, Yamakavagga","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-5:text_original","title":"Dhammapada","text":"Na hi verena verāni, sammantīdha kudācanaṃ;\naverena ca sammanti, esa dhammo sanantano.","lang":"pi","roman":"na hi verena verāni, sammantīdha kudāchanaṃ;\naverena cha sammanti, esa dhammo sanantano."},"vm-dhp-5":{"route":"#/verses/dhammapada","source":"Dhammapada 5 — chapter 1, Yamakavagga","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-5:meaning_kid","title":"What it means · Dhammapada","body":"Hating somebody back has never once stopped the hating. Only not hating stops it. That has always been true and it still is."},"vy-dhp-5":{"route":"#/verses/dhammapada","source":"Dhammapada 5 — chapter 1, Yamakavagga","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-5:why","title":"Why carry it","body":"The playground version: hitting back does not end it. It just makes it their turn again, and then yours, and it can go on for years."},"vs-dhp-49":{"route":"#/verses/dhammapada","source":"Dhammapada 49 — chapter 4, Pupphavagga (“flowers”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-49:text_original","title":"Dhammapada","text":"Yathāpi bhamaro pupphaṃ, vaṇṇagandhamaheṭhayaṃ;\npaleti rasam ādāya, evaṃ gāme munī care.","lang":"pi","roman":"yathāpi bhamaro pupphaṃ, vaṇṇa-gandham-aheṭhayaṃ;\npaleti rasam ādāya, evaṃ gāme munī chare."},"vm-dhp-49":{"route":"#/verses/dhammapada","source":"Dhammapada 49 — chapter 4, Pupphavagga (“flowers”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-49:meaning_kid","title":"What it means · Dhammapada","body":"A bee lands on a flower, takes the nectar and flies off without damaging its colour or its smell. Move through a place like that."},"vy-dhp-49":{"route":"#/verses/dhammapada","source":"Dhammapada 49 — chapter 4, Pupphavagga (“flowers”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-49:why","title":"Why carry it","body":"Take what you need, leave the place as good as you found it. It is a rule for a park, a library, a friend’s house and a shared box of crayons."},"vs-dhp-50":{"route":"#/verses/dhammapada","source":"Dhammapada 50 — chapter 4, Pupphavagga (“flowers”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-50:text_original","title":"Dhammapada","text":"Na paresaṃ vilomāni, na paresaṃ katākataṃ;\nattano va avekkheyya, katāni akatāni ca.","lang":"pi","roman":"na paresaṃ vilomāni, na paresaṃ katākataṃ;\nattano va avekkheyya, katāni akatāni cha."},"vm-dhp-50":{"route":"#/verses/dhammapada","source":"Dhammapada 50 — chapter 4, Pupphavagga (“flowers”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-50:meaning_kid","title":"What it means · Dhammapada","body":"Do not spend your day on what other people got wrong, or on what they did and did not do. Look at your own list instead."},"vy-dhp-50":{"route":"#/verses/dhammapada","source":"Dhammapada 50 — chapter 4, Pupphavagga (“flowers”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-50:why","title":"Why carry it","body":"Extremely useful about one second before you say “but he did it too”. It is always true, and it has never once helped."},"vs-dhp-103":{"route":"#/verses/dhammapada","source":"Dhammapada 103 — chapter 8, Sahassavagga (“the thousands”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-103:text_original","title":"Dhammapada","text":"Yo sahassaṃ sahassena, saṅgāme mānuse jine;\nekañca jeyyamattānaṃ, sa ve saṅgāmajuttamo.","lang":"pi","roman":"yo sahassaṃ sahassena, saṅgāme mānuse jine;\nekañcha jeyyam-attānaṃ, sa ve saṅgāma-juttamo."},"vm-dhp-103":{"route":"#/verses/dhammapada","source":"Dhammapada 103 — chapter 8, Sahassavagga (“the thousands”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-103:meaning_kid","title":"What it means · Dhammapada","body":"Beat a thousand people a thousand times over and you still are not the greatest winner. The greatest is the one who can win against themselves."},"vy-dhp-103":{"route":"#/verses/dhammapada","source":"Dhammapada 103 — chapter 8, Sahassavagga (“the thousands”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-103:why","title":"Why carry it","body":"The hardest opponent you will ever get is the part of you that wants to quit, or shout, or open the game instead of the homework."},"vs-dhp-129":{"route":"#/verses/dhammapada","source":"Dhammapada 129 — chapter 10, Dandavagga (“the rod”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-129:text_original","title":"Dhammapada","text":"Sabbe tasanti daṇḍassa, sabbe bhāyanti maccuno;\nattānaṃ upamaṃ katvā, na haneyya na ghātaye.","lang":"pi","roman":"sabbe tasanti daṇḍassa, sabbe bhāyanti machchuno;\nattānaṃ upamaṃ katvā, na haneyya na ghātaye."},"vm-dhp-129":{"route":"#/verses/dhammapada","source":"Dhammapada 129 — chapter 10, Dandavagga (“the rod”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-129:meaning_kid","title":"What it means · Dhammapada","body":"Everybody is frightened of being hurt. Everybody. So think about yourself for one second — then do not hurt anyone, and do not get anybody else to do it for you either."},"vy-dhp-129":{"route":"#/verses/dhammapada","source":"Dhammapada 129 — chapter 10, Dandavagga (“the rod”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-129:why","title":"Why carry it","body":"The second half is the sharp bit. It is not enough to keep your own hands clean while you stand at the back of the crowd cheering somebody else on."},"vs-dhp-183":{"route":"#/verses/dhammapada","source":"Dhammapada 183 — chapter 14, Buddhavagga","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-183:text_original","title":"Dhammapada","text":"Sabbapāpassa akaraṇaṃ, kusalassa upasampadā;\nsacittapariyodapanaṃ, etaṃ buddhāna sāsanaṃ.","lang":"pi","roman":"sabba-pāpassa akaraṇaṃ, kusalassa upasampadā;\nsa-chitta-pariyodapanaṃ, etaṃ buddhāna sāsanaṃ."},"vm-dhp-183":{"route":"#/verses/dhammapada","source":"Dhammapada 183 — chapter 14, Buddhavagga","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-183:meaning_kid","title":"What it means · Dhammapada","body":"Three things. Do nothing harmful. Do the good you can. Keep your own mind clear. That is the entire teaching in one verse."},"vy-dhp-183":{"route":"#/verses/dhammapada","source":"Dhammapada 183 — chapter 14, Buddhavagga","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-183:why","title":"Why carry it","body":"If you only ever learn one verse from this book, families who keep it will usually tell you it is this one."},"vs-dhp-223":{"route":"#/verses/dhammapada","source":"Dhammapada 223 — chapter 17, Kodhavagga (“anger”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-223:text_original","title":"Dhammapada","text":"Akkodhena jine kodhaṃ, asādhuṃ sādhunā jine;\njine kadariyaṃ dānena, saccenālikavādinaṃ.","lang":"pi","roman":"akkodhena jine kodhaṃ, asādhuṃ sādhunā jine;\njine kadariyaṃ dānena, sachchenālika-vādinaṃ."},"vm-dhp-223":{"route":"#/verses/dhammapada","source":"Dhammapada 223 — chapter 17, Kodhavagga (“anger”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-223:meaning_kid","title":"What it means · Dhammapada","body":"Beat anger by not getting angry. Beat meanness by being good. Beat not-sharing by sharing. Beat a lie by telling the truth."},"vy-dhp-223":{"route":"#/verses/dhammapada","source":"Dhammapada 223 — chapter 17, Kodhavagga (“anger”)","art":null,"cta":"More verses","why":"A verse from Dhammapada","src":"verse:dhp-223:why","title":"Why carry it","body":"Four fights and four ways to win them, and not one of them involves shouting. Try the third one on a sibling and watch what happens."},"vs-subh-vidyadhanam":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. Frequently attributed to Bhartrihari’s Nitishataka, but it circulates independently in many anthologies and the attribution is not settled.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-vidyadhanam:text_original","title":"Subhashitas","text":"न चोरहार्यं न च राजहार्यं\nन भ्रातृभाज्यं न च भारकारि।\nव्यये कृते वर्धत एव नित्यं\nविद्याधनं सर्वधनप्रधानम्॥","lang":"sa","roman":"na corahāryaṃ na ca rājahāryaṃ\nna bhrātṛbhājyaṃ na ca bhārakāri.\nvyaye kṛte vardhata eva nityaṃ\nvidyādhanaṃ sarvadhanapradhānam."},"vm-subh-vidyadhanam":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. Frequently attributed to Bhartrihari’s Nitishataka, but it circulates independently in many anthologies and the attribution is not settled.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-vidyadhanam:meaning_kid","title":"What it means · Subhashitas","body":"A thief cannot steal it. A king cannot take it. Your brother cannot demand half. It weighs nothing to carry. And every time you spend it, you have more of it. That is what knowing things is like."},"vy-subh-vidyadhanam":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. Frequently attributed to Bhartrihari’s Nitishataka, but it circulates independently in many anthologies and the attribution is not settled.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-vidyadhanam:why","title":"Why carry it","body":"Explain something to a friend who did not get it. Notice that you now understand it better than before you opened your mouth. That is the last line."},"vs-subh-vidya-vinaya":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita, widely printed in school readers and often placed in the Hitopadesha. Author and original collection uncertain.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-vidya-vinaya:text_original","title":"Subhashitas","text":"विद्या ददाति विनयं विनयाद्याति पात्रताम्।\nपात्रत्वाद्धनमाप्नोति धनाद्धर्मं ततः सुखम्॥","lang":"sa","roman":"vidyā dadāti vinayaṃ vinayād yāti pātratām.\npātratvād dhanam āpnoti dhanād dharmaṃ tataḥ sukham."},"vm-subh-vidya-vinaya":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita, widely printed in school readers and often placed in the Hitopadesha. Author and original collection uncertain.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-vidya-vinaya:meaning_kid","title":"What it means · Subhashitas","body":"Really learning something makes you humble, not show-offy. Being humble makes people trust you with things. And it goes on from there."},"vy-subh-vidya-vinaya":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita, widely printed in school readers and often placed in the Hitopadesha. Author and original collection uncertain.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-vidya-vinaya:why","title":"Why carry it","body":"The people who actually know the most are almost never the loudest in the room. You have probably already noticed this about a teacher you like."},"vs-subh-udyamena":{"route":"#/verses/subhashita","source":"Hitopadesha, in the opening “Mitralabha” book. Verse numbering varies between editions, so none is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-udyamena:text_original","title":"Subhashitas","text":"उद्यमेन हि सिध्यन्ति कार्याणि न मनोरथैः।\nन हि सुप्तस्य सिंहस्य प्रविशन्ति मुखे मृगाः॥","lang":"sa","roman":"udyamena hi sidhyanti kāryāṇi na manorathaiḥ.\nna hi suptasya siṃhasya praviśanti mukhe mṛgāḥ."},"vm-subh-udyamena":{"route":"#/verses/subhashita","source":"Hitopadesha, in the opening “Mitralabha” book. Verse numbering varies between editions, so none is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-udyamena:meaning_kid","title":"What it means · Subhashitas","body":"Things get done by doing them, not by wishing. Deer do not walk into a sleeping lion’s mouth — even a lion has to get up."},"vy-subh-udyamena":{"route":"#/verses/subhashita","source":"Hitopadesha, in the opening “Mitralabha” book. Verse numbering varies between editions, so none is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-udyamena:why","title":"Why carry it","body":"Being the strongest, the cleverest or the fastest changes nothing at all on a day when you do not start. The lion is not the point. The getting up is."},"vs-subh-kaka-pika":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. Author unknown; it appears in many anthologies with no agreed original collection.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-kaka-pika:text_original","title":"Subhashitas","text":"काकः कृष्णः पिकः कृष्णः को भेदः पिककाकयोः।\nवसन्तसमये प्राप्ते काकः काकः पिकः पिकः॥","lang":"sa","roman":"kākaḥ kṛṣṇaḥ pikaḥ kṛṣṇaḥ ko bhedaḥ pikakākayoḥ.\nvasantasamaye prāpte kākaḥ kākaḥ pikaḥ pikaḥ."},"vm-subh-kaka-pika":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. Author unknown; it appears in many anthologies with no agreed original collection.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-kaka-pika:meaning_kid","title":"What it means · Subhashitas","body":"The crow is black. The cuckoo is black. So what is the difference? Wait for spring. Then the crow is a crow and the cuckoo is a cuckoo — because one of them can sing."},"vy-subh-kaka-pika":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. Author unknown; it appears in many anthologies with no agreed original collection.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-kaka-pika:why","title":"Why carry it","body":"Nobody can tell who practised and who did not, right up until the moment everyone has to play. Then it takes about four seconds."},"vs-subh-mani-sarpa":{"route":"#/verses/subhashita","source":"Bhartrihari, Nitishataka — the verse is standard in that collection, though the Nitishataka’s own verse order differs between editions, so no number is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-mani-sarpa:text_original","title":"Subhashitas","text":"दुर्जनः परिहर्तव्यो विद्ययालङ्कृतोऽपि सन्।\nमणिना भूषितः सर्पः किमसौ न भयङ्करः॥","lang":"sa","roman":"durjanaḥ parihartavyo vidyayālaṅkṛto ’pi san.\nmaṇinā bhūṣitaḥ sarpaḥ kim asau na bhayaṅkaraḥ."},"vm-subh-mani-sarpa":{"route":"#/verses/subhashita","source":"Bhartrihari, Nitishataka — the verse is standard in that collection, though the Nitishataka’s own verse order differs between editions, so no number is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-mani-sarpa:meaning_kid","title":"What it means · Subhashitas","body":"Stay away from someone unkind even if they are very clever. A snake wearing a jewel on its head is still a snake."},"vy-subh-mani-sarpa":{"route":"#/verses/subhashita","source":"Bhartrihari, Nitishataka — the verse is standard in that collection, though the Nitishataka’s own verse order differs between editions, so no number is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-mani-sarpa:why","title":"Why carry it","body":"Clever is not the same as safe, and funny is not the same as kind. The kid everyone laughs with can still be the one everyone is a bit scared of."},"vs-subh-udyoginam":{"route":"#/verses/subhashita","source":"Hitopadesha, in the opening “Prastavika” section. Verse numbering differs between editions, so none is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-udyoginam:text_original","title":"Subhashitas","text":"उद्योगिनं पुरुषसिंहमुपैति लक्ष्मीः\nदैवेन देयमिति कापुरुषा वदन्ति।\nदैवं निहत्य कुरु पौरुषमात्मशक्त्या\nयत्ने कृते यदि न सिध्यति कोऽत्र दोषः॥","lang":"sa","roman":"udyoginaṃ puruṣasiṃham upaiti lakṣmīḥ\ndaivena deyam iti kāpuruṣā vadanti.\ndaivaṃ nihatya kuru pauruṣam ātmaśaktyā\nyatne kṛte yadi na sidhyati ko ’tra doṣaḥ."},"vm-subh-udyoginam":{"route":"#/verses/subhashita","source":"Hitopadesha, in the opening “Prastavika” section. Verse numbering differs between editions, so none is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-udyoginam:meaning_kid","title":"What it means · Subhashitas","body":"Good things come to the person who gets on with it. Push luck aside and use your own strength. And if you really tried and it still did not work — then nothing has gone wrong."},"vy-subh-udyoginam":{"route":"#/verses/subhashita","source":"Hitopadesha, in the opening “Prastavika” section. Verse numbering differs between editions, so none is claimed here.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-udyoginam:why","title":"Why carry it","body":"That last line is the kind one, and most people never quote it. Trying and not winning is not a failure. It is just Tuesday."},"vs-subh-paropakarah":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. It CLAIMS Vyasa and the eighteen Puranas, but it is a later summarising verse about them, not a quotation found in them. Author unknown.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-paropakarah:text_original","title":"Subhashitas","text":"अष्टादशपुराणेषु व्यासस्य वचनद्वयम्।\nपरोपकारः पुण्याय पापाय परपीडनम्॥","lang":"sa","roman":"aṣṭādaśapurāṇeṣu vyāsasya vacanadvayam.\nparopakāraḥ puṇyāya pāpāya parapīḍanam."},"vm-subh-paropakarah":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. It CLAIMS Vyasa and the eighteen Puranas, but it is a later summarising verse about them, not a quotation found in them. Author unknown.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-paropakarah:meaning_kid","title":"What it means · Subhashitas","body":"The verse says: in eighteen enormous books, the sage Vyasa said really only two things. Helping other people is good. Hurting other people is not. That is it."},"vy-subh-paropakarah":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita. It CLAIMS Vyasa and the eighteen Puranas, but it is a later summarising verse about them, not a quotation found in them. Author unknown.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-paropakarah:why","title":"Why carry it","body":"Somebody once read an entire shelf and came back with a sentence a six-year-old can use. That is what a good summary looks like."},"vs-subh-pustakastha":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita, usually printed under the Chanakya Niti heading. Attribution to Chanakya is conventional, not established.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-pustakastha:text_original","title":"Subhashitas","text":"पुस्तकस्था तु या विद्या परहस्तगतं धनम्।\nकार्यकाले समुत्पन्ने न सा विद्या न तद्धनम्॥","lang":"sa","roman":"pustakasthā tu yā vidyā parahastagataṃ dhanam.\nkāryakāle samutpanne na sā vidyā na tad dhanam."},"vm-subh-pustakastha":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita, usually printed under the Chanakya Niti heading. Attribution to Chanakya is conventional, not established.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-pustakastha:meaning_kid","title":"What it means · Subhashitas","body":"Learning that stays inside the book, and money that is in somebody else’s pocket: when you actually need them, you have neither."},"vy-subh-pustakastha":{"route":"#/verses/subhashita","source":"Traditional Sanskrit subhashita, usually printed under the Chanakya Niti heading. Attribution to Chanakya is conventional, not established.","art":null,"cta":"More verses","why":"A verse from Subhashitas","src":"verse:subh-pustakastha:why","title":"Why carry it","body":"Owning the book is not the same as having read it, and having read it is not the same as being able to do it. Ask anyone the night before a test."},"vs-gita-2-47":{"route":"#/verses/gita","source":"Bhagavad Gita 2.47 — chapter 2, “Sankhya Yoga”, verse 47; within the Bhishma Parva of the Mahabharata","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-2-47:text_original","title":"Bhagavad Gita","text":"कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥","lang":"sa","roman":"karmaṇy evādhikāras te mā phaleṣu kadācana.\nmā karmaphalahetur bhūr mā te saṅgo ’stv akarmaṇi."},"vm-gita-2-47":{"route":"#/verses/gita","source":"Bhagavad Gita 2.47 — chapter 2, “Sankhya Yoga”, verse 47; within the Bhishma Parva of the Mahabharata","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-2-47:meaning_kid","title":"What it means · Bhagavad Gita","body":"The work in front of you is yours to do. How it turns out afterwards is not the part you control. So do not let the prize be your only reason — and do not use that as an excuse to stop, either."},"vy-gita-2-47":{"route":"#/verses/gita","source":"Bhagavad Gita 2.47 — chapter 2, “Sankhya Yoga”, verse 47; within the Bhishma Parva of the Mahabharata","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-2-47:why","title":"Why carry it","body":"You practised for six weeks and came fourth. This verse is about what to do with the next morning, and it is the most quoted line in the book."},"vs-gita-2-63":{"route":"#/verses/gita","source":"Bhagavad Gita 2.63 — chapter 2, “Sankhya Yoga”, verse 63","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-2-63:text_original","title":"Bhagavad Gita","text":"क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः।\nस्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति॥","lang":"sa","roman":"krodhād bhavati sammohaḥ sammohāt smṛtivibhramaḥ.\nsmṛtibhraṃśād buddhināśo buddhināśāt praṇaśyati."},"vm-gita-2-63":{"route":"#/verses/gita","source":"Bhagavad Gita 2.63 — chapter 2, “Sankhya Yoga”, verse 63","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-2-63:meaning_kid","title":"What it means · Bhagavad Gita","body":"Anger makes you confused. Confusion makes you forget things. Forgetting wrecks your good sense — and then you are the one who is wrecked."},"vy-gita-2-63":{"route":"#/verses/gita","source":"Bhagavad Gita 2.63 — chapter 2, “Sankhya Yoga”, verse 63","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-2-63:why","title":"Why carry it","body":"It explains, step by step, why you said the thing you would never normally say, about nine seconds after you got furious."},"vs-gita-6-5":{"route":"#/verses/gita","source":"Bhagavad Gita 6.5 — chapter 6, “Dhyana Yoga”, verse 5","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-6-5:text_original","title":"Bhagavad Gita","text":"उद्धरेदात्मनात्मानं नात्मानमवसादयेत्।\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः॥","lang":"sa","roman":"uddhared ātmanātmānaṃ nātmānam avasādayet.\nātmaiva hy ātmano bandhur ātmaiva ripur ātmanaḥ."},"vm-gita-6-5":{"route":"#/verses/gita","source":"Bhagavad Gita 6.5 — chapter 6, “Dhyana Yoga”, verse 5","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-6-5:meaning_kid","title":"What it means · Bhagavad Gita","body":"Pull yourself up. Do not push yourself down. You can be your own best friend and you can be your own worst enemy, and it is the same person doing both."},"vy-gita-6-5":{"route":"#/verses/gita","source":"Bhagavad Gita 6.5 — chapter 6, “Dhyana Yoga”, verse 5","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-6-5:why","title":"Why carry it","body":"The voice in your head the moment you get something wrong. This verse is about whose voice that is, and about the fact that you get a say in it."},"vs-gita-6-17":{"route":"#/verses/gita","source":"Bhagavad Gita 6.17 — chapter 6, “Dhyana Yoga”, verse 17","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-6-17:text_original","title":"Bhagavad Gita","text":"युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु।\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा॥","lang":"sa","roman":"yuktāhāravihārasya yuktaceṣṭasya karmasu.\nyuktasvapnāvabodhasya yogo bhavati duḥkhahā."},"vm-gita-6-17":{"route":"#/verses/gita","source":"Bhagavad Gita 6.17 — chapter 6, “Dhyana Yoga”, verse 17","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-6-17:meaning_kid","title":"What it means · Bhagavad Gita","body":"Eat a sensible amount, play a sensible amount, work a sensible amount, sleep and wake at sensible times. Do that, and the practice stops being a struggle and starts taking your unhappiness away."},"vy-gita-6-17":{"route":"#/verses/gita","source":"Bhagavad Gita 6.17 — chapter 6, “Dhyana Yoga”, verse 17","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-6-17:why","title":"Why carry it","body":"The Gita’s advice for a rotten week is not heroic at all. It is: eat properly and go to bed. Two chapters earlier it was talking about a battlefield."},"vs-gita-12-13":{"route":"#/verses/gita","source":"Bhagavad Gita 12.13 — chapter 12, “Bhakti Yoga”, verse 13","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-12-13:text_original","title":"Bhagavad Gita","text":"अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।\nनिर्ममो निरहङ्कारः समदुःखसुखः क्षमी॥","lang":"sa","roman":"adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca.\nnirmamo nirahaṅkāraḥ samaduḥkhasukhaḥ kṣamī."},"vm-gita-12-13":{"route":"#/verses/gita","source":"Bhagavad Gita 12.13 — chapter 12, “Bhakti Yoga”, verse 13","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-12-13:meaning_kid","title":"What it means · Bhagavad Gita","body":"Hating no living thing. Friendly to everyone. Sorry for anyone who is hurting. Not grabby, not showing off, steady when things go well and when they do not, and quick to forgive."},"vy-gita-12-13":{"route":"#/verses/gita","source":"Bhagavad Gita 12.13 — chapter 12, “Bhakti Yoga”, verse 13","art":null,"cta":"More verses","why":"A verse from Bhagavad Gita","src":"verse:gita-12-13:why","title":"Why carry it","body":"It is a list of what a good person actually looks like on a normal Tuesday. No speeches in it anywhere — just how you are with people."},"fe-lohri":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:kid","title":"Lohri · January","text":"ਲੋਹੜੀ","body":"On the coldest night of the Punjabi year, everyone lights a big bonfire and stands around it. You throw popcorn and sesame sweets into the flames and wish for a good year.","why":"Lohri falls in January"},"fd-lohri-0":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:do:0","title":"Something to do for Lohri","body":"Light one candle after dark and stand around it with whoever is home — this is a fire-and-cold festival, and a candle counts.","why":"One thing to try at home"},"fd-lohri-1":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:do:1","title":"Something to do for Lohri","body":"Make popcorn. Popcorn is genuinely the Lohri food and it costs nothing.","why":"One thing to try at home"},"fd-lohri-2":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:do:2","title":"Something to do for Lohri","body":"Learn the first line of \"Sunder mundriye\" and sing it badly at someone. That is the correct way to sing it.","why":"One thing to try at home"},"fd-lohri-3":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:do:3","title":"Something to do for Lohri","body":"Go outside for one minute in the cold, then come back to the warm. That is the whole feeling of the festival.","why":"One thing to try at home"},"fd-lohri-4":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:do:4","title":"Something to do for Lohri","body":"Call the coldest-living relative you have and tell them Happy Lohri.","why":"One thing to try at home"},"fv-lohri-0":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:variations:0","title":"Lohri, in many families","body":"In many Punjabi families the biggest Lohri is the first one after a wedding or a new baby, and the whole extended family turns up for that one.","why":"Every family keeps it its own way"},"fv-lohri-1":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:variations:1","title":"Lohri, in many families","body":"In many Sikh and Hindu Punjabi households the same night is kept, and the day after is Maghi — which is a gurdwara morning, not a bonfire.","why":"Every family keeps it its own way"},"fv-lohri-2":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:variations:2","title":"Lohri, in many families","body":"In Jammu the same turn of the season is called Lohri too, and in the hills of Himachal the bonfire is smaller and the singing goes on longer.","why":"Every family keeps it its own way"},"pf-lohri":{"route":"#/festival/lohri","art":null,"cta":"Open Lohri","src":"festival:lohri:states:0","title":"Where is it kept?","play":{"q":"Lohri is kept in one of these. Which?","opts":["Punjab","Assam","Ladakh"],"a":0,"after":"Lohri is kept in Punjab, Haryana, Chandigarh, Himachal Pradesh, Delhi, Jammu & Kashmir."},"why":"A festival question"},"fe-makar-sankranti":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:kid","title":"Makar Sankranti · January","text":"मकर संक्रांति","body":"This is the day the sun starts moving back towards the north, so the days get longer again. In lots of places people fly kites all day until they can’t see them any more.","why":"Makar Sankranti falls in January"},"fd-makar-sankranti-0":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:do:0","title":"Something to do for Makar Sankranti","body":"Fly a kite, or make one out of a paper bag and string and fly it badly. Badly is fine.","why":"One thing to try at home"},"fd-makar-sankranti-1":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:do:1","title":"Something to do for Makar Sankranti","body":"Eat something with sesame in it and say the Marathi line that goes with it: \"til gul ghya, god god bola\" — take this sweet, and speak sweetly.","why":"One thing to try at home"},"fd-makar-sankranti-2":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:do:2","title":"Something to do for Makar Sankranti","body":"Find out what your family calls this day. It has at least eight names and yours is one of them.","why":"One thing to try at home"},"fd-makar-sankranti-3":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:do:3","title":"Something to do for Makar Sankranti","body":"Stand outside and notice that it is light later than it was in December. That is literally what the festival is about.","why":"One thing to try at home"},"fv-makar-sankranti-0":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:variations:0","title":"Makar Sankranti, in many families","body":"In many Gujarati families it is Uttarayan and it is a kite war on the roof, all day, with a whole vocabulary for cutting someone else’s string.","why":"Every family keeps it its own way"},"fv-makar-sankranti-1":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:variations:1","title":"Makar Sankranti, in many families","body":"In many Maharashtrian families you hand people til-gul and say \"til gul ghya, god god bola\" — and that sentence does the work of an apology, if one was needed.","why":"Every family keeps it its own way"},"fv-makar-sankranti-2":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:variations:2","title":"Makar Sankranti, in many families","body":"In many Bengali families it is Poush Sankranti and the day is about pithe — rice-flour sweets with date-palm jaggery — not kites at all.","why":"Every family keeps it its own way"},"fv-makar-sankranti-3":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:variations:3","title":"Makar Sankranti, in many families","body":"In many Assamese families the same turn is Magh Bihu, with a night of feasting and bonfires; in many Tamil families it is Pongal.","why":"Every family keeps it its own way"},"pf-makar-sankranti":{"route":"#/festival/makar-sankranti","art":null,"cta":"Open Makar Sankranti","src":"festival:makar-sankranti:states:0","title":"Where is it kept?","play":{"q":"Makar Sankranti is kept in one of these. Which?","opts":["Gujarat","Kerala","Puducherry"],"a":0,"after":"Makar Sankranti is kept in Gujarat, Maharashtra, Uttar Pradesh, Bihar, Rajasthan, Madhya Pradesh, Karnataka, Andhra Pradesh, Telangana, West Bengal, Odisha, Jharkhand, Haryana, Punjab, Assam."},"why":"A festival question"},"fe-pongal":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:kid","title":"Pongal · January","text":"பொங்கல்","body":"Rice and milk are boiled in a pot until they bubble right over the edge — and when they spill, everyone shouts \"Pongalo Pongal!\" The spilling over is the point: it means plenty.","why":"Pongal falls in January"},"fd-pongal-0":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:do:0","title":"Something to do for Pongal","body":"Boil rice in milk in the biggest pot you are allowed to use, and let it rise over the rim. Shout \"Pongalo Pongal!\" when it does.","why":"One thing to try at home"},"fd-pongal-1":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:do:1","title":"Something to do for Pongal","body":"Draw a kolam at the front door with chalk. Outside a flat, the corridor floor works and it washes off.","why":"One thing to try at home"},"fd-pongal-2":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:do:2","title":"Something to do for Pongal","body":"Thank an animal out loud on Mattu Pongal. A dog, a cat, or the cows in a picture.","why":"One thing to try at home"},"fd-pongal-3":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:do:3","title":"Something to do for Pongal","body":"On the last day, go and see somebody — a neighbour, a cousin on a call. That is what Kaanum Pongal is for.","why":"One thing to try at home"},"fd-pongal-4":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:do:4","title":"Something to do for Pongal","body":"Say \"Iniya Pongal nalvazhthukkal\" to one Tamil-speaking person.","why":"One thing to try at home"},"fv-pongal-0":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:variations:0","title":"Pongal, in many families","body":"In many Tamil families the pot is a brand-new one every year, tied with turmeric and ginger still on the root, and nobody uses last year’s.","why":"Every family keeps it its own way"},"fv-pongal-1":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:variations:1","title":"Pongal, in many families","body":"In many Tamil families in Sri Lanka and Malaysia the same four days are kept with slightly different foods and the same shout.","why":"Every family keeps it its own way"},"fv-pongal-2":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:variations:2","title":"Pongal, in many families","body":"In many Andhra and Telangana families the same days are Sankranti, with rangavalli at the door and a very different food list.","why":"Every family keeps it its own way"},"pf-pongal":{"route":"#/festival/pongal","art":null,"cta":"Open Pongal","src":"festival:pongal:states:0","title":"Where is it kept?","play":{"q":"Pongal is kept in one of these. Which?","opts":["Tamil Nadu","Maharashtra","Telangana"],"a":0,"after":"Pongal is kept in Tamil Nadu, Puducherry, Kerala, Karnataka, Andaman & Nicobar Islands."},"why":"A festival question"},"fe-maha-shivaratri":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:kid","title":"Maha Shivaratri · February, March","text":"महाशिवरात्रि","body":"This is Shiva’s night, and people stay awake for it. Milk and water are poured over the Shivling, and bel leaves are offered, and in many houses somebody tries very hard not to fall asleep.","why":"Maha Shivaratri falls in February"},"fd-maha-shivaratri-0":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:do:0","title":"Something to do for Maha Shivaratri","body":"Try to stay up half an hour past bedtime with a grown-up. That is a child-sized vigil and it counts.","why":"One thing to try at home"},"fd-maha-shivaratri-1":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:do:1","title":"Something to do for Maha Shivaratri","body":"Learn to say \"Om Namah Shivaya\" and say it five times slowly.","why":"One thing to try at home"},"fd-maha-shivaratri-2":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:do:2","title":"Something to do for Maha Shivaratri","body":"Pour water over a stone in the garden or a plant pot and think about what it is for. Water is the whole offering.","why":"One thing to try at home"},"fd-maha-shivaratri-3":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:do:3","title":"Something to do for Maha Shivaratri","body":"Find the Ganga on the map and follow it from the Himalaya to the sea, because Shiva is said to have caught it in his hair.","why":"One thing to try at home"},"fv-maha-shivaratri-0":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:variations:0","title":"Maha Shivaratri, in many families","body":"In many Kashmiri Pandit families this is Herath, kept over several days at home with walnuts soaked in water, and it is the family festival of the year.","why":"Every family keeps it its own way"},"fv-maha-shivaratri-1":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:variations:1","title":"Maha Shivaratri, in many families","body":"In many Tamil families the night is spent at the temple with the Thiruvasagam sung aloud; in many Telugu families the fast is strict and the temple queue starts before dawn.","why":"Every family keeps it its own way"},"fv-maha-shivaratri-2":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:variations:2","title":"Maha Shivaratri, in many families","body":"In many families nobody fasts at all and the day is simply a quiet temple visit — that is also normal, and your family gets to decide.","why":"Every family keeps it its own way"},"pf-maha-shivaratri":{"route":"#/festival/maha-shivaratri","art":null,"cta":"Open Maha Shivaratri","src":"festival:maha-shivaratri:states:0","title":"Where is it kept?","play":{"q":"Maha Shivaratri is kept in one of these. Which?","opts":["Uttar Pradesh","Chandigarh","Jharkhand"],"a":0,"after":"Maha Shivaratri is kept in Uttar Pradesh, Madhya Pradesh, Rajasthan, Gujarat, Maharashtra, Karnataka, Tamil Nadu, Andhra Pradesh, Telangana, Jammu & Kashmir, Himachal Pradesh, Uttarakhand, Odisha, West Bengal, Bihar, Kerala."},"why":"A festival question"},"fe-holi":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:kid","title":"Holi · February, March","text":"होली","body":"This is the day everyone is allowed to throw colour at everyone else, and nobody is allowed to be cross about it. The night before, there is a bonfire.","why":"Holi falls in February"},"fd-holi-0":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:do:0","title":"Something to do for Holi","body":"Put one colour on one person’s cheek and say \"Bura na mano, Holi hai\". Ask first; in a country where this isn’t a public holiday, asking first is part of it.","why":"One thing to try at home"},"fd-holi-1":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:do:1","title":"Something to do for Holi","body":"Make colour from turmeric, beetroot juice or spinach water. This is how it used to be made anyway.","why":"One thing to try at home"},"fd-holi-2":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:do:2","title":"Something to do for Holi","body":"Eat something sweet you are not usually allowed to. Gujiya if someone will make it; anything if not.","why":"One thing to try at home"},"fd-holi-3":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:do:3","title":"Something to do for Holi","body":"Wear the oldest clothes you own all day, on purpose, and enjoy that nobody can tell you off about them.","why":"One thing to try at home"},"fd-holi-4":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:do:4","title":"Something to do for Holi","body":"Send a photo of your coloured face to someone in India and let them be jealous of your Tuesday.","why":"One thing to try at home"},"fv-holi-0":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:variations:0","title":"Holi, in many families","body":"In many Braj families around Mathura and Barsana, Holi runs for days and includes Lathmar Holi, where the women of Barsana chase the men off with sticks and everyone finds this hilarious.","why":"Every family keeps it its own way"},"fv-holi-1":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:variations:1","title":"Holi, in many families","body":"In many Bengali families the day is Dol Jatra or Basanta Utsav, with songs and dry colour and white clothes, and it looks nothing like a north Indian Holi.","why":"Every family keeps it its own way"},"fv-holi-2":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:variations:2","title":"Holi, in many families","body":"In many Goan families the season is Shigmo, with folk processions and drums; in many Maharashtrian and Malwa families the colour day is Rang Panchami, several days after the bonfire.","why":"Every family keeps it its own way"},"pf-holi":{"route":"#/festival/holi","art":null,"cta":"Open Holi","src":"festival:holi:states:0","title":"Where is it kept?","play":{"q":"Holi is kept in one of these. Which?","opts":["Uttar Pradesh","Karnataka","Nagaland"],"a":0,"after":"Holi is kept in Uttar Pradesh, Bihar, Madhya Pradesh, Rajasthan, Haryana, Delhi, Punjab, Gujarat, Maharashtra, West Bengal, Odisha, Jharkhand, Chhattisgarh, Uttarakhand, Goa."},"why":"A festival question"},"fe-ugadi-gudi-padwa":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:kid","title":"Ugadi · Gudi Padwa · March, April","text":"ఉగాది · ಯುಗಾದಿ · गुढी पाडवा","body":"This is New Year in several parts of India. In some houses you eat one thing that is sweet and bitter and sour and hot all at once — because a year has all of those in it.","why":"Ugadi · Gudi Padwa falls in March"},"fd-ugadi-gudi-padwa-0":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:do:0","title":"Something to do for Ugadi · Gudi Padwa","body":"Taste something bitter and something sweet in the same mouthful — a tiny bit of dark chocolate and a raisin will do — and say out loud what the year might hold.","why":"One thing to try at home"},"fd-ugadi-gudi-padwa-1":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:do:1","title":"Something to do for Ugadi · Gudi Padwa","body":"Make a gudi: a scarf tied to a broom handle by the door, with a cup upside down on top.","why":"One thing to try at home"},"fd-ugadi-gudi-padwa-2":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:do:2","title":"Something to do for Ugadi · Gudi Padwa","body":"Write one thing you want to get better at this year and put it where you will see it.","why":"One thing to try at home"},"fd-ugadi-gudi-padwa-3":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:do:3","title":"Something to do for Ugadi · Gudi Padwa","body":"Say \"Ugadi subhakankshalu\" or \"Gudi Padwa chya hardik shubhechha\", depending on which is yours.","why":"One thing to try at home"},"fv-ugadi-gudi-padwa-0":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:variations:0","title":"Ugadi · Gudi Padwa, in many families","body":"In many Marathi families the gudi goes up at sunrise and comes down before sunset, and neighbours compare whose is highest.","why":"Every family keeps it its own way"},"fv-ugadi-gudi-padwa-1":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:variations:1","title":"Ugadi · Gudi Padwa, in many families","body":"In many Telugu and Kannada families the day begins with the pachadi or bevu-bella and then the panchangam — the year’s almanac — is read aloud to the family.","why":"Every family keeps it its own way"},"fv-ugadi-gudi-padwa-2":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:variations:2","title":"Ugadi · Gudi Padwa, in many families","body":"In many Sindhi families the same season brings Cheti Chand, and in many Kashmiri Pandit families it is Navreh — different names, the same turn of the year.","why":"Every family keeps it its own way"},"pf-ugadi-gudi-padwa":{"route":"#/festival/ugadi-gudi-padwa","art":null,"cta":"Open Ugadi · Gudi Padwa","src":"festival:ugadi-gudi-padwa:states:0","title":"Where is it kept?","play":{"q":"Ugadi · Gudi Padwa is kept in one of these. Which?","opts":["Andhra Pradesh","Delhi","Meghalaya"],"a":0,"after":"Ugadi · Gudi Padwa is kept in Andhra Pradesh, Telangana, Karnataka, Maharashtra, Goa, Madhya Pradesh."},"why":"A festival question"},"fe-navroz":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:kid","title":"Navroz · March, July, August","text":"નવરોઝ","body":"This is New Year for Parsi families in India. The house is cleaned, a special table is laid out with things that mean good luck, and everyone visits everyone.","why":"Navroz falls in March"},"fd-navroz-0":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:do:0","title":"Something to do for Navroz","body":"Clean your room properly before the day, not on it. That is the actual custom and it is not a trick.","why":"One thing to try at home"},"fd-navroz-1":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:do:1","title":"Something to do for Navroz","body":"Lay out five things on a table that mean something good to you and explain each one to someone.","why":"One thing to try at home"},"fd-navroz-2":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:do:2","title":"Something to do for Navroz","body":"Say \"Navroz Mubarak\" to a Parsi friend if you have one, and look up the Parsi community of Mumbai if you don’t.","why":"One thing to try at home"},"fd-navroz-3":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:do:3","title":"Something to do for Navroz","body":"Draw a chalk pattern at your own front door.","why":"One thing to try at home"},"fv-navroz-0":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:variations:0","title":"Navroz, in many families","body":"Some Parsi families keep Navroz in March at the spring equinox, and others keep it in July or August, because two different Parsi calendars are in use — both are right, and both are kept in the same city.","why":"Every family keeps it its own way"},"fv-navroz-1":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:variations:1","title":"Navroz, in many families","body":"In many Parsi families in Mumbai the day is as much about lunch as anything else, and the dhansak and the sev come out for it.","why":"Every family keeps it its own way"},"pf-navroz":{"route":"#/festival/navroz","art":null,"cta":"Open Navroz","src":"festival:navroz:states:0","title":"Where is it kept?","play":{"q":"Navroz is kept in one of these. Which?","opts":["Maharashtra","Jharkhand","Punjab"],"a":0,"after":"Navroz is kept in Maharashtra, Gujarat, Delhi, Karnataka."},"why":"A festival question"},"fe-mahavir-jayanti":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:kid","title":"Mahavir Jayanti · March, April","text":"महावीर जयंती","body":"This is the birthday of Mahavira, the twenty-fourth Jain teacher. It is a gentle day — no noise, no fireworks, and nobody eats anything that had to be harmed.","why":"Mahavir Jayanti falls in March"},"fd-mahavir-jayanti-0":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:do:0","title":"Something to do for Mahavir Jayanti","body":"Eat one meal that harmed nothing, and notice how much thinking that takes.","why":"One thing to try at home"},"fd-mahavir-jayanti-1":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:do:1","title":"Something to do for Mahavir Jayanti","body":"Move an insect outside instead of the other thing. That is ahimsa, exactly.","why":"One thing to try at home"},"fd-mahavir-jayanti-2":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:do:2","title":"Something to do for Mahavir Jayanti","body":"Say something you were about to say more kindly. Jains count words as a way of causing harm too.","why":"One thing to try at home"},"fd-mahavir-jayanti-3":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:do:3","title":"Something to do for Mahavir Jayanti","body":"Learn what anekantavada means — many-sidedness — and try it in one argument this week.","why":"One thing to try at home"},"fv-mahavir-jayanti-0":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:variations:0","title":"Mahavir Jayanti, in many families","body":"In many Jain families the day is quiet and spent at the derasar or the temple; in many others there is a large procession through the town and the whole community walks it.","why":"Every family keeps it its own way"},"fv-mahavir-jayanti-1":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:variations:1","title":"Mahavir Jayanti, in many families","body":"In many Shvetambara and Digambara families the customs differ — Jains are not one single practice either, and it is worth asking which yours is.","why":"Every family keeps it its own way"},"pf-mahavir-jayanti":{"route":"#/festival/mahavir-jayanti","art":null,"cta":"Open Mahavir Jayanti","src":"festival:mahavir-jayanti:states:0","title":"Where is it kept?","play":{"q":"Mahavir Jayanti is kept in one of these. Which?","opts":["Gujarat","Uttarakhand","Dadra & Nagar Haveli"],"a":0,"after":"Mahavir Jayanti is kept in Gujarat, Rajasthan, Maharashtra, Madhya Pradesh, Karnataka, Tamil Nadu, Delhi, Uttar Pradesh, Bihar, Jharkhand."},"why":"A festival question"},"fe-bihu":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:kid","title":"Bihu · January, April, October","text":"বিহু","body":"Assam has three Bihus in a year — one for planting, one for eating, and one quiet one in between. The spring one is the big dance, with a drum and a buffalo-horn pipe.","why":"Bihu falls in January"},"fd-bihu-0":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:do:0","title":"Something to do for Bihu","body":"Give somebody a cloth — a scarf, a towel, anything — with both hands, the way a gamosa is given. Both hands is the whole point.","why":"One thing to try at home"},"fd-bihu-1":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:do:1","title":"Something to do for Bihu","body":"Find a beat on a table with both hands and keep it while somebody else dances. Bihu runs on the dhol.","why":"One thing to try at home"},"fd-bihu-2":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:do:2","title":"Something to do for Bihu","body":"Eat something made of rice and coconut. Assamese pitha is exactly that.","why":"One thing to try at home"},"fd-bihu-3":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:do:3","title":"Something to do for Bihu","body":"Find the Brahmaputra on the map and see how wide it is, then find Kaziranga next to it.","why":"One thing to try at home"},"fv-bihu-0":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:variations:0","title":"Bihu, in many families","body":"In many Assamese families the January Bihu is the one about food and the April one is the one about dancing, and people are very clear which they prefer.","why":"Every family keeps it its own way"},"fv-bihu-1":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:variations:1","title":"Bihu, in many families","body":"In many Assamese families the gamosa is given to elders on Bihu morning as a way of touching their feet without saying anything — and it is one of the warmest customs in India.","why":"Every family keeps it its own way"},"fv-bihu-2":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:variations:2","title":"Bihu, in many families","body":"Many other Northeast communities keep their own spring and harvest festivals in the same weeks, under their own names.","why":"Every family keeps it its own way"},"pf-bihu":{"route":"#/festival/bihu","art":null,"cta":"Open Bihu","src":"festival:bihu:states:0","title":"Where is it kept?","play":{"q":"Bihu is kept in one of these. Which?","opts":["Assam","Sikkim","Chhattisgarh"],"a":0,"after":"Bihu is kept in Assam, Arunachal Pradesh, Meghalaya, Nagaland."},"why":"A festival question"},"fe-vishu":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:kid","title":"Vishu · April","text":"വിഷു","body":"On Vishu morning a grown-up leads you to a table with your eyes shut, and then you open them. The first thing you see on New Year is supposed to be something good.","why":"Vishu falls in April"},"fd-vishu-0":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:do:0","title":"Something to do for Vishu","body":"Arrange five good things on a table the night before and lead somebody to it with their eyes shut in the morning.","why":"One thing to try at home"},"fd-vishu-1":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:do:1","title":"Something to do for Vishu","body":"Find one yellow flower and put it on the table. In Kerala it would be kanikkonna.","why":"One thing to try at home"},"fd-vishu-2":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:do:2","title":"Something to do for Vishu","body":"Give a coin to somebody younger than you and say \"Vishu ashamsakal\".","why":"One thing to try at home"},"fd-vishu-3":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:do:3","title":"Something to do for Vishu","body":"Notice what the first thing you saw this morning was, and whether it was worth seeing.","why":"One thing to try at home"},"fv-vishu-0":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:variations:0","title":"Vishu, in many families","body":"In many Malayali families the Vishukkani is arranged the night before by the mother and nobody else is allowed to look at it early.","why":"Every family keeps it its own way"},"fv-vishu-1":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:variations:1","title":"Vishu, in many families","body":"In many families in northern Kerala the day includes Vishu padakkam — small firecrackers at dawn — and in many others it stays entirely quiet.","why":"Every family keeps it its own way"},"pf-vishu":{"route":"#/festival/vishu","art":null,"cta":"Open Vishu","src":"festival:vishu:states:0","title":"Where is it kept?","play":{"q":"Vishu is kept in one of these. Which?","opts":["Kerala","Andaman & Nicobar Islands","Gujarat"],"a":0,"after":"Vishu is kept in Kerala, Karnataka, Tamil Nadu, Puducherry."},"why":"A festival question"},"fe-puthandu":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:kid","title":"Puthandu · April","text":"புத்தாண்டு","body":"Tamil New Year. There is a dish you eat on this day that is sweet and sour and bitter and hot all at once, so that you taste the whole year in one spoon.","why":"Puthandu falls in April"},"fd-puthandu-0":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:do:0","title":"Something to do for Puthandu","body":"Taste four things in one sitting: something sweet, sour, bitter and spicy. Say which part of a year each one is.","why":"One thing to try at home"},"fd-puthandu-1":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:do:1","title":"Something to do for Puthandu","body":"Draw a kolam at the door with chalk, or with rice flour if you are allowed.","why":"One thing to try at home"},"fd-puthandu-2":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:do:2","title":"Something to do for Puthandu","body":"Say \"Puthandu vazhthukkal\" to a Tamil-speaking person.","why":"One thing to try at home"},"fd-puthandu-3":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:do:3","title":"Something to do for Puthandu","body":"Set the table for someone else before they wake up.","why":"One thing to try at home"},"fv-puthandu-0":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:variations:0","title":"Puthandu, in many families","body":"In many Tamil families the kani is seen first thing and nothing else happens until it has been; in many others the day is mostly the temple and the meal.","why":"Every family keeps it its own way"},"fv-puthandu-1":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:variations:1","title":"Puthandu, in many families","body":"In many Tamil families in Sri Lanka, Malaysia and Singapore the same day is kept, which is why \"Tamil New Year\" is a public holiday in more than one country.","why":"Every family keeps it its own way"},"pf-puthandu":{"route":"#/festival/puthandu","art":null,"cta":"Open Puthandu","src":"festival:puthandu:states:0","title":"Where is it kept?","play":{"q":"Puthandu is kept in one of these. Which?","opts":["Tamil Nadu","Delhi","Maharashtra"],"a":0,"after":"Puthandu is kept in Tamil Nadu, Puducherry, Kerala, Andaman & Nicobar Islands."},"why":"A festival question"},"fe-poila-boishakh":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:kid","title":"Poila Boishakh · April","text":"পয়লা বৈশাখ","body":"Bengali New Year. Shops open a brand-new account book, everyone wears new clothes, and there are more sweets in the house than on any other day.","why":"Poila Boishakh falls in April"},"fd-poila-boishakh-0":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:do:0","title":"Something to do for Poila Boishakh","body":"Start a brand-new notebook today and write the date at the top. That is halkhata, done exactly right.","why":"One thing to try at home"},"fd-poila-boishakh-1":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:do:1","title":"Something to do for Poila Boishakh","body":"Eat something sweet before anything else — Bengali New Year genuinely begins with mishti.","why":"One thing to try at home"},"fd-poila-boishakh-2":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:do:2","title":"Something to do for Poila Boishakh","body":"Say \"Shubho Noboborsho\" to somebody.","why":"One thing to try at home"},"fd-poila-boishakh-3":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:do:3","title":"Something to do for Poila Boishakh","body":"Sing or play one Rabindrasangeet and find out who wrote it.","why":"One thing to try at home"},"fv-poila-boishakh-0":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:variations:0","title":"Poila Boishakh, in many families","body":"In many Bengali families the day begins with a visit to the sweetshop and ends with a very large fish; in many others it is mostly music.","why":"Every family keeps it its own way"},"fv-poila-boishakh-1":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:variations:1","title":"Poila Boishakh, in many families","body":"In many Bengali families in Bangladesh and in Tripura the same day is kept with its own processions — the new year does not stop at a border.","why":"Every family keeps it its own way"},"pf-poila-boishakh":{"route":"#/festival/poila-boishakh","art":null,"cta":"Open Poila Boishakh","src":"festival:poila-boishakh:states:0","title":"Where is it kept?","play":{"q":"Poila Boishakh is kept in one of these. Which?","opts":["West Bengal","Lakshadweep","Rajasthan"],"a":0,"after":"Poila Boishakh is kept in West Bengal, Tripura, Assam, Jharkhand, Andaman & Nicobar Islands."},"why":"A festival question"},"fe-buddha-purnima":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:kid","title":"Buddha Purnima · April, May","text":"बुद्ध पूर्णिमा","body":"On this full-moon day Buddhists remember the Buddha. Temples are lit with lamps, people give food away, and many families eat nothing that had to be harmed.","why":"Buddha Purnima falls in April"},"fd-buddha-purnima-0":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:do:0","title":"Something to do for Buddha Purnima","body":"Sit still and count ten breaths. Ten. That is a real meditation and it is where everyone starts.","why":"One thing to try at home"},"fd-buddha-purnima-1":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:do:1","title":"Something to do for Buddha Purnima","body":"Give something away today without being asked — food, a toy, your turn.","why":"One thing to try at home"},"fd-buddha-purnima-2":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:do:2","title":"Something to do for Buddha Purnima","body":"Eat one meal that harmed nothing.","why":"One thing to try at home"},"fd-buddha-purnima-3":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:do:3","title":"Something to do for Buddha Purnima","body":"Look up at the moon tonight and check that it is full. It is the calendar this festival runs on.","why":"One thing to try at home"},"fv-buddha-purnima-0":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:variations:0","title":"Buddha Purnima, in many families","body":"In many Ladakhi, Sikkimese and Arunachali families the day is spent at a monastery, and butter lamps are lit in rows.","why":"Every family keeps it its own way"},"fv-buddha-purnima-1":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:variations:1","title":"Buddha Purnima, in many families","body":"In many Buddhist families in Maharashtra the day is kept alongside the memory of Dr Ambedkar, who chose Buddhism in 1956 and brought many others with him.","why":"Every family keeps it its own way"},"fv-buddha-purnima-2":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:variations:2","title":"Buddha Purnima, in many families","body":"Buddhism left India and changed as it travelled, so a Thai, Sri Lankan, Japanese and Ladakhi Buddha Purnima look genuinely different from one another.","why":"Every family keeps it its own way"},"pf-buddha-purnima":{"route":"#/festival/buddha-purnima","art":null,"cta":"Open Buddha Purnima","src":"festival:buddha-purnima:states:0","title":"Where is it kept?","play":{"q":"Buddha Purnima is kept in one of these. Which?","opts":["Bihar","Lakshadweep","Puducherry"],"a":0,"after":"Buddha Purnima is kept in Bihar, Uttar Pradesh, Sikkim, Arunachal Pradesh, Ladakh, Jammu & Kashmir, Himachal Pradesh, Maharashtra, West Bengal, Tripura, Karnataka, Delhi."},"why":"A festival question"},"fe-thrissur-pooram":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:kid","title":"Thrissur Pooram · April, May","text":"തൃശ്ശൂർ പൂരം","body":"In one town in Kerala, rows of elephants stand facing each other in front of a temple while hundreds of drummers play together. The people up on the elephants swap enormous silk parasols above their heads, over and over, and the crowd roars every time.","why":"Thrissur Pooram falls in April"},"fd-thrissur-pooram-0":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:do:0","title":"Something to do for Thrissur Pooram","body":"Listen to a recording of chenda melam with a grown-up and try to hear it speeding up. It does that for an hour.","why":"One thing to try at home"},"fd-thrissur-pooram-1":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:do:1","title":"Something to do for Thrissur Pooram","body":"Clap in time with somebody for two full minutes without either of you drifting. That is what a hundred drummers do for hours.","why":"One thing to try at home"},"fd-thrissur-pooram-2":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:do:2","title":"Something to do for Thrissur Pooram","body":"Find Thrissur on the map of Kerala.","why":"One thing to try at home"},"fd-thrissur-pooram-3":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:do:3","title":"Something to do for Thrissur Pooram","body":"Talk about elephants: why they are honoured here, and why more and more people in Kerala are now arguing about whether they should be in the festival at all. Both things are true at once.","why":"One thing to try at home"},"fv-thrissur-pooram-0":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:variations:0","title":"Thrissur Pooram, in many families","body":"In many Malayali families the Pooram is a day out with a huge crowd and very loud drums; in many others the family stays home and watches it on television, which is also a tradition now.","why":"Every family keeps it its own way"},"fv-thrissur-pooram-1":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:variations:1","title":"Thrissur Pooram, in many families","body":"Almost every Kerala temple has its own pooram or utsavam at its own time of year — Thrissur is the one outsiders have heard of, not the only one that matters.","why":"Every family keeps it its own way"},"pf-thrissur-pooram":{"route":"#/festival/thrissur-pooram","art":null,"cta":"Open Thrissur Pooram","src":"festival:thrissur-pooram:states:0","title":"Where is it kept?","play":{"q":"Thrissur Pooram is kept in one of these. Which?","opts":["Kerala","Madhya Pradesh","Uttar Pradesh"],"a":0,"after":"Thrissur Pooram is kept in Kerala."},"why":"A festival question"},"fe-ratha-yatra":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:kid","title":"Ratha Yatra · June, July","text":"ରଥଯାତ୍ରା","body":"Once a year at Puri, three deities come out of their temple and ride through the town on three enormous wooden chariots. The chariots are pulled along the road by the crowd, on long ropes, by hand.","why":"Ratha Yatra falls in June"},"fd-ratha-yatra-0":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:do:0","title":"Something to do for Ratha Yatra","body":"Sweep the floor before an important guest arrives. At Puri the sweeping is done first, by hand, and it matters.","why":"One thing to try at home"},"fd-ratha-yatra-1":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:do:1","title":"Something to do for Ratha Yatra","body":"Build a chariot from a box and string and pull it down the hall with somebody riding on it.","why":"One thing to try at home"},"fd-ratha-yatra-2":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:do:2","title":"Something to do for Ratha Yatra","body":"Find Puri on the coast of Odisha on the map.","why":"One thing to try at home"},"fd-ratha-yatra-3":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:do:3","title":"Something to do for Ratha Yatra","body":"Learn that \"juggernaut\" is an Odia word that got into English, and tell someone at school.","why":"One thing to try at home"},"fv-ratha-yatra-0":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:variations:0","title":"Ratha Yatra, in many families","body":"In many Odia families this is the festival of the year, and relatives travel home for it the way other families travel for Diwali.","why":"Every family keeps it its own way"},"fv-ratha-yatra-1":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:variations:1","title":"Ratha Yatra, in many families","body":"In many Bengali families a small household version is kept, with a little chariot pulled by the children of the street.","why":"Every family keeps it its own way"},"fv-ratha-yatra-2":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:variations:2","title":"Ratha Yatra, in many families","body":"In Ahmedabad and in cities all over the world, local Ratha Yatras are held by communities who cannot get to Puri.","why":"Every family keeps it its own way"},"pf-ratha-yatra":{"route":"#/festival/ratha-yatra","art":null,"cta":"Open Ratha Yatra","src":"festival:ratha-yatra:states:0","title":"Where is it kept?","play":{"q":"Ratha Yatra is kept in one of these. Which?","opts":["Odisha","Dadra & Nagar Haveli","Meghalaya"],"a":0,"after":"Ratha Yatra is kept in Odisha, West Bengal, Gujarat, Jharkhand, Assam, Tripura."},"why":"A festival question"},"fe-teej":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:kid","title":"Teej · July, August, September","text":"तीज","body":"The rains have finally come, everything has gone green, and swings are hung from the trees. Hands are covered in mehndi and there is a lot of singing.","why":"Teej falls in July"},"fd-teej-0":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:do:0","title":"Something to do for Teej","body":"Get on a swing. Any swing. This festival is about swings and rain and it works anywhere.","why":"One thing to try at home"},"fd-teej-1":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:do:1","title":"Something to do for Teej","body":"Draw a mehndi pattern on your own hand with a felt pen.","why":"One thing to try at home"},"fd-teej-2":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:do:2","title":"Something to do for Teej","body":"Go outside in the rain on purpose, if it is raining. If it isn’t, this is a good day to be jealous of India.","why":"One thing to try at home"},"fd-teej-3":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:do:3","title":"Something to do for Teej","body":"Wear something green.","why":"One thing to try at home"},"fd-teej-4":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:do:4","title":"Something to do for Teej","body":"Learn one line of a Teej song from a grown-up who knows one.","why":"One thing to try at home"},"fv-teej-0":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:variations:0","title":"Teej, in many families","body":"In many Rajasthani families Teej is a fair with processions in Jaipur, and green bangles and ghewar are the whole taste of the season.","why":"Every family keeps it its own way"},"fv-teej-1":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:variations:1","title":"Teej, in many families","body":"In many families in Uttar Pradesh and Bihar the day is a fast kept by married women; in many others it is simply the swing, the songs and the mehndi, kept by everybody.","why":"Every family keeps it its own way"},"fv-teej-2":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:variations:2","title":"Teej, in many families","body":"In many Nepali and Himalayan Indian families Teej is kept over several days with its own songs entirely.","why":"Every family keeps it its own way"},"pf-teej":{"route":"#/festival/teej","art":null,"cta":"Open Teej","src":"festival:teej:states:0","title":"Where is it kept?","play":{"q":"Teej is kept in one of these. Which?","opts":["Rajasthan","Telangana","Chhattisgarh"],"a":0,"after":"Teej is kept in Rajasthan, Uttar Pradesh, Bihar, Haryana, Punjab, Madhya Pradesh, Jharkhand, Delhi, Uttarakhand."},"why":"A festival question"},"fe-raksha-bandhan":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:kid","title":"Raksha Bandhan · July, August","text":"रक्षाबंधन","body":"A sister ties a thread on her brother’s wrist, and he promises to look after her — and usually gives her something. The thread stays on until it falls off by itself.","why":"Raksha Bandhan falls in July"},"fd-raksha-bandhan-0":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:do:0","title":"Something to do for Raksha Bandhan","body":"Make a rakhi from thread, wool or ribbon and tie it on somebody. It does not have to be a brother — many families now tie for cousins, friends and sisters.","why":"One thing to try at home"},"fd-raksha-bandhan-1":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:do:1","title":"Something to do for Raksha Bandhan","body":"Post one to a cousin in another country, early, because post is slow.","why":"One thing to try at home"},"fd-raksha-bandhan-2":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:do:2","title":"Something to do for Raksha Bandhan","body":"Tie one on a video call and get them to hold their wrist up to the camera. This is a real thing families do.","why":"One thing to try at home"},"fd-raksha-bandhan-3":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:do:3","title":"Something to do for Raksha Bandhan","body":"Promise one specific thing you will actually do, rather than \"look after them\". Specific promises get kept.","why":"One thing to try at home"},"fv-raksha-bandhan-0":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:variations:0","title":"Raksha Bandhan, in many families","body":"In many families in Maharashtra and coastal Gujarat, the same full moon is Narali Purnima, when coconuts are offered to the sea before the fishing boats go out again.","why":"Every family keeps it its own way"},"fv-raksha-bandhan-1":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:variations:1","title":"Raksha Bandhan, in many families","body":"In many Tamil, Telugu and Malayali families the same day is Avani Avittam or Upakarmam, when the sacred thread is changed — a completely different observance on the same date.","why":"Every family keeps it its own way"},"fv-raksha-bandhan-2":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:variations:2","title":"Raksha Bandhan, in many families","body":"In many families there is no brother to tie for, and the rakhi goes to a cousin, a friend or a sister instead. That is now extremely common and entirely normal.","why":"Every family keeps it its own way"},"pf-raksha-bandhan":{"route":"#/festival/raksha-bandhan","art":null,"cta":"Open Raksha Bandhan","src":"festival:raksha-bandhan:states:0","title":"Where is it kept?","play":{"q":"Raksha Bandhan is kept in one of these. Which?","opts":["Uttar Pradesh","Andaman & Nicobar Islands","Goa"],"a":0,"after":"Raksha Bandhan is kept in Uttar Pradesh, Madhya Pradesh, Rajasthan, Haryana, Delhi, Punjab, Gujarat, Maharashtra, Bihar, Jharkhand, Chhattisgarh, Uttarakhand, West Bengal, Karnataka."},"why":"A festival question"},"fe-janmashtami":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:kid","title":"Janmashtami · August, September","text":"जन्माष्टमी","body":"This is Krishna’s birthday, and he was born at midnight — so people stay up for it. As a baby he was famous for stealing butter, so on this day there is butter everywhere.","why":"Janmashtami falls in August"},"fd-janmashtami-0":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:do:0","title":"Something to do for Janmashtami","body":"Stay up until midnight if you are allowed. If you are not, celebrate loudly at eight and blame the time difference.","why":"One thing to try at home"},"fd-janmashtami-1":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:do:1","title":"Something to do for Janmashtami","body":"Make tiny footprints from the front door to wherever the baby Krishna would be. Rice flour or chalk.","why":"One thing to try at home"},"fd-janmashtami-2":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:do:2","title":"Something to do for Janmashtami","body":"Build a human pyramid with cushions and a toy on top, and pull it down. This is dahi handi, indoors and safe.","why":"One thing to try at home"},"fd-janmashtami-3":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:do:3","title":"Something to do for Janmashtami","body":"Eat butter on something and say sorry to nobody.","why":"One thing to try at home"},"fd-janmashtami-4":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:do:4","title":"Something to do for Janmashtami","body":"Swing a cradle — a shoebox on a string will do — because in the south the baby is put in a swing.","why":"One thing to try at home"},"fv-janmashtami-0":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:variations:0","title":"Janmashtami, in many families","body":"In many Maharashtrian families the day belongs to the dahi handi in the street, and the pyramid teams train for weeks.","why":"Every family keeps it its own way"},"fv-janmashtami-1":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:variations:1","title":"Janmashtami, in many families","body":"In many Tamil families it is Gokulashtami, with little footprints drawn in rice flour leading into the house, and seedai and murukku made for it.","why":"Every family keeps it its own way"},"fv-janmashtami-2":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:variations:2","title":"Janmashtami, in many families","body":"In many Gujarati and Braj families the temples at Mathura and Dwarka set the tone, with jhankis — tableaux of the story — and singing all night.","why":"Every family keeps it its own way"},"pf-janmashtami":{"route":"#/festival/janmashtami","art":null,"cta":"Open Janmashtami","src":"festival:janmashtami:states:0","title":"Where is it kept?","play":{"q":"Janmashtami is kept in one of these. Which?","opts":["Uttar Pradesh","Ladakh","Sikkim"],"a":0,"after":"Janmashtami is kept in Uttar Pradesh, Maharashtra, Gujarat, Rajasthan, Madhya Pradesh, Haryana, Delhi, Tamil Nadu, Karnataka, Andhra Pradesh, Telangana, Odisha, West Bengal, Bihar, Manipur."},"why":"A festival question"},"fe-ganesh-chaturthi":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:kid","title":"Ganesh Chaturthi · August, September","text":"गणेश चतुर्थी","body":"Ganesha comes to stay. A clay Ganesha is brought into the house, looked after like a guest for a few days, and then taken to the water and let go — and everybody says \"come back soon next year\".","why":"Ganesh Chaturthi falls in August"},"fd-ganesh-chaturthi-0":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:do:0","title":"Something to do for Ganesh Chaturthi","body":"Make a Ganesha from clay or salt dough, keep him on a shelf for two days, and dissolve him in a bucket at the end. That is the whole festival, correctly done.","why":"One thing to try at home"},"fd-ganesh-chaturthi-1":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:do:1","title":"Something to do for Ganesh Chaturthi","body":"Make or eat a modak, or any sweet dumpling. Steamed if you can.","why":"One thing to try at home"},"fd-ganesh-chaturthi-2":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:do:2","title":"Something to do for Ganesh Chaturthi","body":"Shout \"Ganpati bappa — morya!\" and get someone to shout the second half back.","why":"One thing to try at home"},"fd-ganesh-chaturthi-3":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:do:3","title":"Something to do for Ganesh Chaturthi","body":"Learn the story of how Ganesha won the race around the world without leaving home.","why":"One thing to try at home"},"fd-ganesh-chaturthi-4":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:do:4","title":"Something to do for Ganesh Chaturthi","body":"Water a plant with the bucket afterwards, so nothing is wasted.","why":"One thing to try at home"},"fv-ganesh-chaturthi-0":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:variations:0","title":"Ganesh Chaturthi, in many families","body":"In many Maharashtrian families Ganpati comes for a day and a half; in many others for five, seven or eleven days, and every family knows exactly which it is.","why":"Every family keeps it its own way"},"fv-ganesh-chaturthi-1":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:variations:1","title":"Ganesh Chaturthi, in many families","body":"In many Goan families the festival is Chavath, kept at home with a decorated wooden canopy called a matoli hung with fruit from the garden — no street pandal at all.","why":"Every family keeps it its own way"},"fv-ganesh-chaturthi-2":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:variations:2","title":"Ganesh Chaturthi, in many families","body":"In many Telugu and Kannada families the festival is kept quietly at home, and in many Tamil families it is Vinayaka Chaturthi with kozhukattai made for it.","why":"Every family keeps it its own way"},"pf-ganesh-chaturthi":{"route":"#/festival/ganesh-chaturthi","art":null,"cta":"Open Ganesh Chaturthi","src":"festival:ganesh-chaturthi:states:0","title":"Where is it kept?","play":{"q":"Ganesh Chaturthi is kept in one of these. Which?","opts":["Maharashtra","Chandigarh","Lakshadweep"],"a":0,"after":"Ganesh Chaturthi is kept in Maharashtra, Goa, Karnataka, Telangana, Andhra Pradesh, Tamil Nadu, Gujarat, Madhya Pradesh, Chhattisgarh, Odisha, Daman & Diu, Dadra & Nagar Haveli."},"why":"A festival question"},"fe-onam":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:kid","title":"Onam · August, September","text":"ഓണം","body":"Once a year the old king Mahabali comes back to visit Kerala, and everyone makes sure he finds it happy. There are flower carpets at every door and a feast eaten off a banana leaf.","why":"Onam falls in August"},"fd-onam-0":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:do:0","title":"Something to do for Onam","body":"Lay a pookalam at your door with petals, or with coloured paper circles if there are no flowers where you live.","why":"One thing to try at home"},"fd-onam-1":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:do:1","title":"Something to do for Onam","body":"Eat one meal off a banana leaf, or off the biggest plate in the house, with your hand. There is a right order to eat a sadya in — ask.","why":"One thing to try at home"},"fd-onam-2":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:do:2","title":"Something to do for Onam","body":"Add one more circle to the pookalam every day for ten days. Its growing is the point.","why":"One thing to try at home"},"fd-onam-3":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:do:3","title":"Something to do for Onam","body":"Say \"Onashamsakal\" to a Malayali person.","why":"One thing to try at home"},"fd-onam-4":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:do:4","title":"Something to do for Onam","body":"Race paper boats in the bath or a puddle and call it vallamkali.","why":"One thing to try at home"},"fv-onam-0":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:variations:0","title":"Onam, in many families","body":"In many Malayali families Onam is kept by Hindu, Christian and Muslim households alike — it is Kerala’s festival before it is anybody’s religious one.","why":"Every family keeps it its own way"},"fv-onam-1":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:variations:1","title":"Onam, in many families","body":"In many families the sadya has twenty-six items and somebody counts; in many others it is eight and nobody minds.","why":"Every family keeps it its own way"},"fv-onam-2":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:variations:2","title":"Onam, in many families","body":"In many Malayali families abroad, the Onam sadya at a hired hall in September is the largest gathering of the year, and everyone brings one dish.","why":"Every family keeps it its own way"},"pf-onam":{"route":"#/festival/onam","art":null,"cta":"Open Onam","src":"festival:onam:states:0","title":"Where is it kept?","play":{"q":"Onam is kept in one of these. Which?","opts":["Kerala","Delhi","Meghalaya"],"a":0,"after":"Onam is kept in Kerala, Tamil Nadu, Karnataka, Puducherry, Lakshadweep."},"why":"A festival question"},"fe-paryushana":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:kid","title":"Paryushana · Das Lakshana · August, September","text":"पर्युषण","body":"For eight or ten days Jains eat simply, listen to readings, and try very hard not to hurt anything. At the end, everyone goes to everyone they know and asks to be forgiven.","why":"Paryushana · Das Lakshana falls in August"},"fd-paryushana-0":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:do:0","title":"Something to do for Paryushana · Das Lakshana","body":"Say sorry properly to one person, to their face, for an old thing. Not sideways, not by text if you can help it.","why":"One thing to try at home"},"fd-paryushana-1":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:do:1","title":"Something to do for Paryushana · Das Lakshana","body":"Say Michhami Dukkadam to your whole family group — Jain families send exactly this message every year.","why":"One thing to try at home"},"fd-paryushana-2":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:do:2","title":"Something to do for Paryushana · Das Lakshana","body":"Eat before it gets dark for one evening, and notice what that changes.","why":"One thing to try at home"},"fd-paryushana-3":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:do:3","title":"Something to do for Paryushana · Das Lakshana","body":"Forgive one person without them asking. That is the harder half of this festival.","why":"One thing to try at home"},"fv-paryushana-0":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:variations:0","title":"Paryushana · Das Lakshana, in many families","body":"In many Shvetambara families it is eight days and the Kalpa Sutra is read aloud; in many Digambara families it is ten days of Das Lakshana. Both are Paryushana and both are right.","why":"Every family keeps it its own way"},"fv-paryushana-1":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:variations:1","title":"Paryushana · Das Lakshana, in many families","body":"In many Jain families the children keep a small fast of their own choosing, and the family makes a proper occasion of it rather than a hardship.","why":"Every family keeps it its own way"},"pf-paryushana":{"route":"#/festival/paryushana","art":null,"cta":"Open Paryushana · Das Lakshana","src":"festival:paryushana:states:0","title":"Where is it kept?","play":{"q":"Paryushana · Das Lakshana is kept in one of these. Which?","opts":["Gujarat","Assam","Jammu & Kashmir"],"a":0,"after":"Paryushana · Das Lakshana is kept in Gujarat, Rajasthan, Maharashtra, Madhya Pradesh, Karnataka, Tamil Nadu, Delhi, Uttar Pradesh, Bihar."},"why":"A festival question"},"fe-navratri":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:kid","title":"Navratri · March, April, September, October","text":"नवरात्रि","body":"Nine nights. In Gujarat everyone dances in circles until very late; in Tamil Nadu people build steps of dolls in the front room and invite the neighbours to come and look.","why":"Navratri falls in March"},"fd-navratri-0":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:do:0","title":"Something to do for Navratri","body":"Learn the basic garba step — clap, step, clap — and do one circle round the kitchen with somebody.","why":"One thing to try at home"},"fd-navratri-1":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:do:1","title":"Something to do for Navratri","body":"Build a golu on three shelves or three stairs with whatever figures you own, and invite someone to come and look at it.","why":"One thing to try at home"},"fd-navratri-2":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:do:2","title":"Something to do for Navratri","body":"Make sundal: boiled chickpeas, coconut, mustard seeds. It is the snack of these nine nights and it takes ten minutes.","why":"One thing to try at home"},"fd-navratri-3":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:do:3","title":"Something to do for Navratri","body":"Find out which of the nine nights your family thinks matters most. Families genuinely differ.","why":"One thing to try at home"},"fv-navratri-0":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:variations:0","title":"Navratri, in many families","body":"In many Gujarati families the whole nine nights are dancing, and children are allowed to stay up far later than usual.","why":"Every family keeps it its own way"},"fv-navratri-1":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:variations:1","title":"Navratri, in many families","body":"In many Tamil, Kannada and Telugu families the nine nights are the Golu, the dolls come out of the same boxes every year, and one figure is added each year.","why":"Every family keeps it its own way"},"fv-navratri-2":{"route":"#/festival/navratri","art":null,"cta":"Open Navratri","src":"festival:navratri:variations:2","title":"Navratri, in many families","body":"In many Bengali families these same days are Durga Puja and look entirely different again.","why":"Every family keeps it its own way"}});
